#include "../../benchmarks/native/dlist_iterator.h"
static void status(enum IterStatus s){puts(s==ITER_OK?"OK":s==ITER_END?"ERR end":"ERR state");}
int main(int argc,char**argv){St s;dl_init(&s,0,1);DIterator it=it_first(&s);for(int i=1;i<argc;i++){char*t=argv[i];uint32_t v=0;enum IterStatus e;if(!strcmp(t,"first")){s=it_finish(&it);it=it_first(&s);puts("OK");}else if(!strcmp(t,"last")){s=it_finish(&it);it=it_last(&s);puts("OK");}else if(!strcmp(t,"next")||!strcmp(t,"prev")){e=!strcmp(t,"next")?it_next(&it,&v):it_previous(&it,&v);if(e==ITER_OK)printf("V %u\n",v);else status(e);}else if(!strncmp(t,"add:",4))status(it_add(&it,(uint32_t)strtoul(t+4,NULL,10)));else if(!strncmp(t,"set:",4))status(it_set(&it,(uint32_t)strtoul(t+4,NULL,10)));else if(!strcmp(t,"remove"))status(it_remove(&it));else if(!strcmp(t,"hn"))printf("B %d\n",it_has_next(&it));else if(!strcmp(t,"hp"))printf("B %d\n",it_has_previous(&it));else if(!strcmp(t,"pos"))printf("N %u\n",it.index);else{printf("LIST ");int comma=0;for(uint32_t n=it.list.head;n!=NO_ID;n=it.list.cells[n].next){printf("%s%u",comma?",":"",it.list.cells[n].val);comma=1;}puts("");}}s=it_finish(&it);free(s.cells);return 0;}
